"""Per-landmark data: OSM refs of the real footprint, front compass bearing (deg), eave metres, description."""
# id: (refs, frontBearingWanted, eaveMetres or None, desc)
I = {
'transamerica_pyramid': (['way/24222973'], 260, 196, "William Pereira's 1972 pyramid, 260 m: a four-sided spike of white crushed-quartz precast concrete panels with rows of small square windows, tapering from a 53 m square base to a point. Two vertical 'wings' (the lift shaft on the east face, the stair and smoke tower on the west) stand proud of the upper 19 floors, and the top 64 m is a hollow aluminium-louvred spire with a beacon. The base stands on a forest of criss-crossing diagonal concrete columns two storeys high; a redwood grove fills the east half of the block."),
'salesforce_tower': (['way/431972186'], 315, 296, "Pelli Clarke Pelli's 2018 tower, 326 m, the tallest in the city: a slender rounded-square obelisk of clear glass wrapped in horizontal white metal sunshade fins, tapering gently and ending in a hollow perforated-aluminium crown about 30 m high that carries a wraparound LED artwork at night. The corners are soft curves; the base opens to Mission St and the transit center's rooftop park."),
'bank_of_america_555_california': (['way/288511106'], 171, 226, "The 1969 Bank of America Center, 237 m: a massive dark slab clad in polished carnelian (red-brown) granite, its whole facade folded into thousands of faceted bay windows of bronze-tinted glass that run in saw-tooth vertical ribs. The top steps back irregularly like a quartz crystal. A dark granite plaza on California St holds the black 'Banker's Heart' sculpture."),
'tower_181_fremont': (['way/445566153'], 45, 213, "The 2018 mixed-use tower, 245 m to the spire tip: a slender, slightly folded shaft of blue-grey glass with a white steel exoskeleton of giant diagonal mega-braces zig-zagging up each face. The facades crease inward along the braces; the top tapers to an asymmetric peak with a thin spire."),
'millennium_tower': (['way/72963089'], 315, 197, "The 2009 condominium tower, 197 m: a soft-cornered slab of blue-grey glass with faint horizontal spandrel bands and a subtly faceted, bowed profile, flat roof. A 12-storey glass mid-rise wing stands beside it on Mission St. (It is the tower famous for sinking and leaning.)"),
'one_rincon_hill': (['way/944990390'], 45, 184, "The 2008 South Tower of One Rincon Hill, 184 m, alone on the hilltop beside the Bay Bridge approach: a slim tower of blue-green glass with one long curved (oval) side and white aluminium fin bands, topped by a canted oval crown band that holds the tuned liquid damper tank and a weather beacon. Townhouse podium of pale concrete at the base."),
'embarcadero_center_1': (['way/32612608'], 351, 170, "One Embarcadero Center (1971, 173 m), John Portman's first tower: a very thin slab of pale ribbed precast concrete stepped back in vertical slices at both ends so the plan narrows like staggered dominoes, narrow vertical window strips between closely spaced fins. It stands on a three-storey podium of shops with open walkways, spiral stairs and footbridges linking all four blocks."),
'embarcadero_center_2': (['way/32612520'], 351, 126, "Two Embarcadero Center (1974, 126 m): the shorter twin of the same thin, stepped slab of pale precast concrete ribs and narrow window strips on the three-storey retail podium with its bridges across the streets."),
'embarcadero_center_3': (['way/32612538'], 351, 126, "Three Embarcadero Center (1977, 126 m): thin stepped slab of pale ribbed precast concrete like its neighbours, on the three-storey podium of shops and open terraces."),
'embarcadero_center_4': (['way/616812910'], 351, 174, "Four Embarcadero Center (1982, 174 m), the east end of the complex beside the Hyatt Regency: the tallest of the four thin, stepped pale concrete slabs with vertical ribs, on the three-storey podium facing Embarcadero Plaza."),
'california_345': (['way/588355355'], 171, 177, "The 1986 345 California Center, 212 m, in the middle of a block behind older bank buildings: a slim tower faced in grey-pink granite and silver-blue glass with chamfered, notched corners. The top eleven floors (a hotel) split into two glass towers turned 45 degrees and joined by glazed skybridges, each crowned by an angled flagpole-like spire."),
'california_101': (['way/1279505488'], 81, 183, "Philip Johnson's 1982 tower, 183 m: a faceted cylinder of silver-grey glass and granite ribs (a serrated 'sawtooth' drum with about 100 small facets) rising from a seven-storey sloping glass atrium wedge at its foot, on a triangular stepped granite plaza with planters where California St meets Market St."),
'montgomery_44': (['way/32963370'], 81, 172, "The 1967 former Wells Fargo headquarters, 172 m: a plain International Style slab, its long faces a tight grid of white aluminium vertical mullions over dark glass, flat top, on a recessed glass lobby at Montgomery and Market."),
'one_market_spear_tower': (['way/132238423'], 45, 172, "The Spear Tower of One Market Plaza (1976, 172 m): a dark bronze-brown slab with closely spaced vertical precast fins and a serrated plan, flat top. It rises behind the 1916 Southern Pacific headquarters, an eleven-storey red-brick and terra cotta block facing the foot of Market St; a lower twin (Steuart Tower) stands to the south-east."),
'fremont_50': (['way/288716396'], 315, 170, "The 1985 50 Fremont Center, 183 m: a square tower of pale grey-pink granite with a regular grid of punched square windows, the corners notched, the top stepping back in several tiers to a small square crown."),
'mckesson_plaza_one_post': (['way/32946671'], 171, 161, "One Post / McKesson Plaza (1969, 161 m): a square bronze-coloured tower, bronze-tinted glass between dark vertical ribs, with chamfered corners and a slight flare at the base, standing over the sunken plaza of the Montgomery St station where Post meets Market."),
'park_tower': (['way/611390934'], 315, 184, "The 2018 Park Tower at Transbay, 184 m: a clear glass office tower with crisp white horizontal fins, cut by three stacked double-height notches (sky decks with trees) that step round its corners, flat top."),
'mission_555': (['way/80296761'], 135, 149, "The 2008 office tower, 149 m: a clean slab of pale green glass, the east and west faces leaning out very slightly, with a tall glass-fin crown and a small plaza of sculptures on Mission St."),
'market_525': (['way/32946570'], 135, 161, "First Market Tower (1973, 161 m): a broad, dark 1970s slab, charcoal precast piers and bronze glass in a strict vertical grid, flat roof, set back from Market St behind a plaza."),
'one_sansome': (['way/32963344'], 81, 168, "One Sansome / Citigroup Center (1984, 168 m): a pale grey-white stone tower with a grid of square windows and rounded bay corners, rising beside the roofless marble banking hall of the 1910 Anglo & London Paris National Bank, kept as an open conservatory at the corner of Sutter and Sansome."),
'infinity_tower_1': (['way/421816062'], 45, 110, "The Infinity, Tower I (2008, about 110 m, 37 storeys): a clover-leaf plan tower with every corner a full curve, wrapped in continuous bands of green-tinted glass and thin white slab edges."),
'infinity_tower_2': (['way/421816061'], 45, 137, "The Infinity, Tower II (2009, 137 m, 42 storeys): the taller of the two curved clover-plan condominium towers, sea-green glass in smooth unbroken bands with white floor edges, flat top; low curved mid-rise blocks sit between the towers."),
'lumina': (['way/421816060'], 45, 122, "Lumina, Tower I (2015, 122 m): the sister of the Infinity one block inland: a curving, lozenge-plan condominium tower of pale blue-green glass with rounded ends and white horizontal bands, beside a shorter twin."),
'russ_building': (['way/129142347'], 81, 123, "The 1927 Russ Building, 133 m, 'the city's first skyscraper': a neo-Gothic E-shaped block of pale cream-grey terra cotta with strong vertical piers, stepping back in tiers to a central tower with Gothic tracery, finials and a flagpole. Deep light courts open to Montgomery St."),
'pacbell_building': (['way/80296766'], 135, 122, "Timothy Pflueger's 1925 Pacific Telephone building, 133 m: an Art Deco / neo-Gothic L-plan tower of speckled grey-white terra cotta, soaring unbroken piers that end in a stepped crown of pinnacles, with eight great terra cotta eagles perched on the top corners. Dark recessed spandrels, ornate black-and-gold lobby entrance on New Montgomery St."),
'shell_building': (['way/260282390'], 171, 105, "The 1929 Shell Building, 115 m: a slender Art Deco tower of rusticated sepia-brown terra cotta, vertical piers rising to a stepped crown decorated with abstract shell forms, once floodlit in gold."),
'hobart_building': (['way/32946628'], 135, 76, "Willis Polk's 1914 Hobart Building, 87 m: a narrow, ornate cream terra cotta tower with an idiosyncratic oval-ended top, Baroque sculpted cornices and a hipped green-copper cap; its flat, bare south flank (exposed when a neighbour was pulled down) faces Market St."),
'hilton_union_square': (['way/79375246'], 351, 150, "Hilton San Francisco Union Square, the 1971 tower, 150 m (46 storeys): a pale concrete hotel slab with a grid of windows between slim vertical ribs and a glazed round-cornered sky lounge on top, rising from the full-block Hilton complex in the Tenderloin (with a second, 1987 tower and the 1964 block round a courtyard)."),
'marriott_marquis': (['way/436648569'], 315, 120, "The 1989 Marriott Marquis, 133 m, 'the jukebox': a broad stepped hotel tower of pale pink-beige precast and silver mirror glass, its top a symmetrical pile of fan-shaped mirrored-glass arches and quarter-circles like a Wurlitzer jukebox, with a great arched window to the View Lounge."),
'intercontinental_sf': (['way/256029743'], 315, 104, "The 2008 InterContinental, 104 m: a slim slab of translucent pale blue-turquoise glass, flat and unmodelled, on a low podium beside Moscone West at 5th and Howard."),
'four_seasons_757_market': (['way/435591307'], 135, 121, "The 2001 Four Seasons hotel and residences, 121 m: a calm grey stone-and-glass tower with rounded glass corner bays, set back from Market St behind a lower shop block."),
'st_regis_sf': (['way/436648187'], 315, 148, "The 2005 St. Regis Museum Tower, 148 m: a slender tower of pale precast concrete and glass with a grid of square windows and a glazed corner, standing over the 1907 brick Williams Building and the Museum of the African Diaspora at 3rd and Mission, next to SFMOMA."),
'westin_st_francis': (['way/332378158', 'way/435582543'], 81, 60, "The Westin St. Francis on the west side of Union Square: the 1904-13 block of grey Colusa sandstone, twelve storeys with three (later four) projecting wings divided by deep light courts, a heavy cornice and a row of flags over the Powell St cable-car line; behind it the 1972 tower, 120 m, a pale concrete slab with five glass capsule lifts running up its outside face."),
'fairmont_sf': (['relation/16217497', 'way/436477702'], 81, 35, "The Fairmont on top of Nob Hill: the 1907 Beaux-Arts palace of white-cream terra cotta and granite, seven storeys, with a columned porte-cochere and a row of flags on Mason St and a roof garden; at its north-east corner the 1961 tower, 99 m, a plain pale slab with an external glass lift to the former Crown Room."),
'mark_hopkins': (['way/1361492525'], 171, 80, "The 1926 Mark Hopkins Hotel, 93 m, on the crest of Nob Hill: a central tower with two splayed wings round a forecourt, buff brick and cream terra cotta in a French chateau / Spanish Renaissance manner, a steep hipped roof with finials, and the glass-walled Top of the Mark lounge on the 19th floor."),
'hyatt_regency_embarcadero': (['way/28319370'], 100, 74, "John Portman's 1973 Hyatt Regency, 74 m: a triangular wedge of pale ribbed concrete whose north face steps back floor by floor in a long slope of balconies (the famous 17-storey atrium is inside), with a low drum of the old revolving restaurant on the roof. It closes the east end of Embarcadero Center at the foot of Market and California Streets."),
'federal_building_sf': (['way/32863953'], 135, 71, "Morphosis' 2007 Federal Building, 71 m: a very thin 18-storey slab only 20 m deep. The south-east face is draped in a folded scrim of perforated stainless steel that rides up over the roof and stops short in mid-air; the north-west face has green glass fins; a three-storey void (sky garden) is cut through the slab. A low annex and a plaza on 7th St."),
'burton_federal_building': (['way/35176305'], 171, 95, "The 1964 Phillip Burton Federal Building and Courthouse, 95 m: a broad 21-storey International Style slab, a uniform grid of pale precast concrete and dark glass, filling a block of Golden Gate Avenue above a bare plaza."),
'fox_plaza': (['way/33790323'], 315, 108, "Fox Plaza (1966, 108 m), on the site of the Fox Theatre at Market and Polk: a plain 29-storey slab, beige precast with horizontal window bands, offices below and apartments with balconies above."),
'sentinel_building': (['way/288485994'], 150, 26, "The 1907 Sentinel Building (Columbus Tower), 30 m: a small eight-storey flatiron at the sharp corner of Columbus Avenue and Kearny St, clad in white tile and copper weathered to pale green, with projecting bay windows up both sides, a rounded prow and a little domed cupola on top. The Transamerica Pyramid rises directly behind it."),
'ferry_building': (['way/558731934'], 240, 17, "A. Page Brown's 1898 Ferry Building at the foot of Market St: a 201 m long, three-storey hall of grey Colusa sandstone on the bulkhead, its west front a continuous arcade of round arches with a skylit nave behind. In the middle rises the 75 m clock tower modelled on the Giralda of Seville, pale grey, with four 6.7 m clock dials, an arcaded belfry and a small cupola with a flagpole."),
'coit_tower': (['way/28824850'], 351, 55, "The 1933 tower on the summit of Telegraph Hill, 64 m: a slender fluted cylinder of unpainted white reinforced concrete, slightly tapered, with an arcaded observation loggia of round arches and a second ring of openings at the top; a low rectangular base holds the murals. It stands in the pines and cypresses of Pioneer Park."),
'sf_city_hall': (['relation/7261820'], 81, 30, "Arthur Brown Jr.'s 1915 City Hall, 94 m: a two-block Beaux-Arts palace of grey Sierra granite with Doric colonnades and pedimented centre porticoes on both long fronts, crowned by a tall dome on a colonnaded drum: lead-grey ribbed dome picked out in gold leaf, with a gilded lantern and torch. The east front faces Civic Center Plaza."),
'grace_cathedral': (['way/32946942'], 81, 28, "The Episcopal cathedral on Nob Hill (1928-64), 75 m to the fleche: French Gothic in exposed pale grey reinforced concrete, modelled on Notre-Dame, with twin square 53 m west towers, a rose window between them, gilded bronze 'Gates of Paradise' doors, flying-buttress-like piers along the nave and a slender lead fleche over the crossing. A broad flight of steps falls east to Taylor St."),
'sts_peter_and_paul': (['way/29902626'], 171, 23, "The 1924 Saints Peter and Paul Church on the north side of Washington Square, 58 m: a white Romanesque-revival front with twin slender spires of open arcaded stages, a rose window and a mosaic band with a line of Dante across the facade; cream-white stucco nave behind."),
'old_st_marys': (['way/260520154'], 171, 19, "Old St. Mary's (1854), the first cathedral of California, at California St and Grant Avenue: a red-brick Gothic Revival church on a granite base with a square central clock tower with battlements, 27 m; under the clock the gilt text 'Son, observe the time and fly from evil'."),
'dragon_gate': ([('node/65328703', 20, 5)], 171, 8, "The 1970 Dragon Gate across Grant Avenue at Bush St, the entrance to Chinatown: three bays (a wide road arch and two footway arches) of grey stone piers carrying roofs of green glazed tile with upturned eaves, two gold dragons chasing a pearl on the main ridge, fish and dolphins on the corners, and a pair of stone guardian lions at the foot."),
'sing_chong_building': (['@sing_chong'], 171, 16, "The 1908 Sing Chong Building at the north-west corner of California St and Grant Avenue: a four-storey buff and cream brick bazaar with green-and-red painted trim and a corner tower in three diminishing pagoda roofs with upturned eaves and a finial, 22 m: the building that set the look of rebuilt Chinatown, facing the cable cars on California St."),
'bank_of_canton_pagoda': (['way/251790077'], 81, 9, "The 1909 Chinese Telephone Exchange on Washington St: a small one-storey pavilion under three tiers of curving green-tiled pagoda roofs with red lacquered columns, gold trim and upturned eaves, about 12 m."),
'oracle_park': (['relation/7325085'], 315, 40, "The Giants' ballpark (2000) on China Basin: a red-brick and green-steel park in the old style, three decks of dark green seats wrapping the infield, a brick arcade and promenade along the right-field wall directly on McCovey Cove (home runs splash into the water), four banks of lights on steel towers, the big scoreboard in centre field, and behind the left-field bleachers a giant old-fashioned baseball glove and a soda-bottle slide. Brick clock towers with pyramid roofs mark the entrances at Willie Mays Plaza."),
'pier_39': (['way/199829618'], 190, 10, "The 1978 shopping pier, about 300 m long: two storeys of grey weathered-timber sheds, shops and restaurants with shingled gables, balconies and outside stairs round a central boardwalk, flagpoles all along the roofs, a two-level Venetian carousel near the outer end, a marina on both sides, and on the west side the floating docks crowded with sea lions."),
'fishermans_wharf_sign': ([('node/5455630121', 6, 2)], 180, 12, "The Fisherman's Wharf sign at Jefferson and Taylor Streets: a round ship's wheel about 6 m across with a red crab in the middle and white lettering round the rim, on a tall post above the crab stands."),
'ghirardelli_square': (['way/27104863'], 351, 25, "The former chocolate works above Aquatic Park, converted in 1964: a full block of red-brick factory buildings with crenellated parapets round terraced courts and a fountain, the 1916 Clock Tower (modelled on the Chateau de Blois, about 40 m) at the south-east corner, and a giant illuminated roof sign in 4.5 m letters on a steel frame facing the bay."),
'balclutha': (['@balclutha'], 171, 8, "The 1886 Clyde-built square-rigger at the Hyde Street Pier: a three-masted full-rigged steel ship, 92 m overall with the bowsprit, black hull with a white strake and red boot-topping, white deckhouses, buff masts and yards about 44 m high with furled sails and a web of rigging."),
'pier_45_ships': (['@pier45ships'], 81, 14, "The museum ships on the east side of Pier 45: SS Jeremiah O'Brien, a 135 m grey Liberty ship of 1943 with a central island, single funnel, cargo masts and gun tubs, and moored astern of her the black-grey Balao-class submarine USS Pampanito, 95 m, low in the water with her fairwater and deck guns."),
'pier_45_sheds': (['way/25372350', 'way/25372352', 'way/25372355'], 171, 10, "The four long Pier 45 sheds (A to D, 1926) at Fisherman's Wharf: white-painted concrete transit sheds in two rows with shallow gabled roofs and neoclassical arched end facades, home of the fish processors and the Musee Mecanique."),
'aquarium_of_the_bay': (['way/288396169'], 190, 12, "The aquarium at the landward end of Pier 39: a two-storey grey timber-clad building with a blue wave-topped entrance and banners on the Embarcadero."),
'exploratorium_pier_15': (['way/25478444'], 240, 12, "The Exploratorium in the 1931 Pier 15 shed: a 250 m long white transit shed with a low gabled roof covered in solar panels running out over the bay, fronted on the Embarcadero by a cream neoclassical bulkhead building with a great central arch."),
'pier_27_cruise_terminal': (['way/262476981'], 260, 14, "The 2014 James R. Herman Cruise Terminal on Pier 27: a long two-storey box of glass and white metal with a folded roof and a projecting gangway gallery, on a broad apron under Telegraph Hill."),
'cupids_span': (['way/175010375'], 45, 18, "Claes Oldenburg and Coosje van Bruggen's 2002 sculpture in Rincon Park: a giant gold bow and red-feathered arrow, 18 m high, the arrow and the middle of the bow buried in the lawn so that the bow arcs like a ship or a suspension bridge against the Bay Bridge."),
'vaillancourt_fountain': ([((37.79552, -122.39528), 42, 30)], 81, 12, "Armand Vaillancourt's 1971 fountain in Embarcadero Plaza: a 12 m tangle of square precast concrete tubes with a rough, rusty-stained texture, jutting at all angles over a pool with stepping-stone slabs."),
'sfmoma': (['way/41692824'], 315, 44, "Mario Botta's 1995 museum on 3rd St: stepped symmetrical boxes of red-brown patterned brick, with a black-and-white striped stone cylinder sliced off at an angle (the oculus) rising in the middle; behind and above it Snohetta's 2016 extension, a 60 m slab of rippled white fibre-reinforced panels like fog or bay water."),
'salesforce_transit_center': (['relation/10725927'], 315, 21, "The 2018 transit center, 440 m long and four storeys, bridging First and Fremont Streets: a low undulating hall wrapped in a white perforated aluminium skin with a Penrose pattern, carried on tree-like V-columns, with a 2 ha rooftop park of lawns and trees along its whole length and a bus bridge to the Bay Bridge at the west end."),
'moscone_center': (['way/109141776'], 315, 25, "Moscone South (rebuilt 2018) on Howard St: a long glass-and-white-steel convention hall front with terraces and footbridges across Howard St to Moscone North; the exhibition halls are underground beneath the roof gardens of Yerba Buena."),
'contemporary_jewish_museum': (['way/118106934'], 135, 14, "Daniel Libeskind's 2008 museum: the red-brick 1907 Jessie Street power substation with a cream terra cotta cornice, skewered by a tilted cube and a skewed block of shimmering blue steel panels standing on one corner."),
'union_square_dewey_monument': (['way/616479962'], 81, 26, "The 1903 Dewey Monument in the centre of Union Square: a 26 m Corinthian column of pale granite on a square pedestal, topped by a bronze Victory holding a trident and a wreath."),
'westfield_dome': (['way/332627424'], 315, 30, "The 1896 Emporium on Market St (now the San Francisco Centre): a grey sandstone Beaux-Arts front with a giant order of columns and a central arch, and behind it the 31 m wide glass-and-steel dome, lifted onto the roof of the new centre."),
'flood_building': (['relation/1547963'], 135, 50, "The 1904 Flood Building at Powell and Market by the cable-car turntable: twelve storeys of grey Colusa sandstone, a flatiron with a rounded corner, a rusticated base, giant-order middle and a heavy cornice."),
'phelan_building': (['relation/1547962'], 100, 45, "The 1908 Phelan Building: an eleven-storey flatiron of glazed cream-white terra cotta filling the point between Market St and O'Farrell St, with a rounded prow and a deep cornice."),
'palace_hotel': (['relation/3492933'], 315, 37, "The 1909 Palace Hotel at Market and New Montgomery: a broad eight-storey block of buff brick with terra cotta trim, roof signs on steel frames, and the glass-roofed Garden Court inside."),
'old_mint': (['way/32863779'], 351, 16, "The 1874 Old Mint, the 'Granite Lady', at 5th and Mission: a severe Greek Revival block of blue-grey sandstone on a granite basement, with a six-column Doric portico and pediment up a broad flight of steps and two tall square chimneys behind."),
'war_memorial_opera_house': (['way/32865161'], 81, 40, "The 1932 War Memorial Opera House on Van Ness Avenue opposite City Hall: a Beaux-Arts block of grey granite and terra cotta, a rusticated base, a row of tall arched windows between paired Doric columns, and a mansard roof; the fly tower rises at the back."),
'war_memorial_veterans_building': (['way/32865757'], 81, 28, "The 1932 Veterans Building (Herbst Theatre), the Opera House's near-twin across the memorial court: grey granite and terra cotta, rusticated base, tall arched windows between paired columns, mansard roof."),
'davies_symphony_hall': (['way/32865746'], 45, 30, "The 1980 Louise M. Davies Symphony Hall: a pale precast concrete hall whose front on Grove St and Van Ness is a great curved wrap of glass lobbies in tiers between concrete fins."),
'asian_art_museum': (['way/24588037'], 261, 25, "The 1917 former Main Library, since 2003 the Asian Art Museum: a Beaux-Arts block of grey granite on the east side of Civic Center Plaza with a row of arched windows and Ionic columns."),
'sf_main_library': (['way/24446086'], 261, 30, "The 1996 Main Library: a grey granite block that echoes its Beaux-Arts neighbours on the Civic Center side and turns to a modern glass-and-metal facade on Market St, with a round skylit atrium."),
'bill_graham_civic_auditorium': (['way/25759141'], 351, 30, "The 1915 Exposition Auditorium on the south side of Civic Center Plaza: a broad grey granite Beaux-Arts block with three great arched windows under a canopy and a low hipped roof."),
'cable_car_barn': (['way/30029681'], 171, 12, "The 1887 / 1907 Washington-Mason car barn and powerhouse: a red-brick block with arched windows and corbelled parapets and a tall square brick chimney, where the great winding wheels drive all the cable-car lines."),
'pacific_union_club': (['way/32947069'], 171, 18, "The 1886 James C. Flood mansion, the only Nob Hill palace to survive 1906: a dark Connecticut brownstone Italianate block of two tall storeys with a columned porch, behind a bronze fence, on California St opposite the Fairmont."),
'caltrain_station': (['way/28295229'], 45, 6, "The Caltrain terminus at 4th and King Streets: a low single-storey 1970s station of tan concrete and glass with a flat canopy at the head of twelve stub tracks and platforms."),
'third_street_bridge': (['way/1088314479'], 351, 12, "The 1933 Lefty O'Doul Bridge by Joseph Strauss: a heel-trunnion bascule carrying 3rd St over the mouth of Mission Creek beside the ballpark: riveted grey-green steel through trusses with a great overhead concrete counterweight on the north tower."),
}
SHED_DESC = "One of the Embarcadero's numbered finger piers (1910s-30s): a cream-white neoclassical bulkhead building on the roadway with a big central arch and the pier number in the pediment, and behind it a long low transit shed with a shallow gabled roof running out over the bay on piles."
